+/** The best supported language for an Accept-Language header value, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const value = Array.isArray(header) ? header.join(",") : header;
+  if (typeof value !== "string" || value.trim() === "") return fallback;
+  const ranges = [];
+  value.split(",").forEach((part, index) => {
+    const [tag, ...params] = part.trim().split(";").map((x) => x.trim());
+    if (!tag) return;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*([0-9.]+)$/i.exec(p);
+      if (m) q = Number(m[1]);
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) return;
+    ranges.push({ tag: tag.toLowerCase(), q, index });
+  });
+  ranges.sort((a, b) => b.q - a.q || a.index - b.index);
+  for (const { tag } of ranges) {
+    if (tag === "*") return fallback;
+    const primary = tag.split("-")[0];
+    if (LANGUAGES.includes(primary)) return primary;
+  }
+  return fallback;
+}
